<script setup>
import { computed, onMounted, onBeforeUnmount, ref, watch } from 'vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
import LocationPicker from '../../Components/LocationPicker.vue';
import { cartKey, readCart, cartLine, choicesValid, money } from '../../Support/cart.js';
import { paymentCountdown } from '../../Support/paymentExpiry.js';
const props = defineProps({ store: Object, period: Object, items: Array, submitUrl: String, quoteUrl: String, backUrl: String, checkoutKey: String, resetCheckoutKey: Boolean, mapTilesUrl: String, bankAccounts: Array, paymentMethods: Object, routingDemo: Boolean, gatewayAvailable: Boolean, paymentDeadline: String, serverNow: String });
const clock = ref(Date.now());
const offset = Date.parse(props.serverNow) - Date.now();
let countdownTimer;
onMounted(() => { countdownTimer = setInterval(() => { clock.value = Date.now(); }, 1000); });
onBeforeUnmount(() => clearInterval(countdownTimer));
const paymentTime = computed(() => paymentCountdown(props.paymentDeadline, clock.value + offset));
const qrisClosed = computed(() => paymentTime.value?.expired === true);
const cart = ref([]); const loaded = ref(false); const quoting = ref(false); const quote = ref(null); const quoteError = ref('');
const keyName = `rintis.checkout-key.${props.period.id}`;
const form = useForm({ idempotency_key: props.checkoutKey, customer_name: '', phone: '', method: props.period.pickup ? 'pickup' : 'delivery', payment_method: props.paymentMethods.cash ? 'cash' : props.paymentMethods.qris ? 'qris' : '', payment_bank: props.gatewayAvailable ? 'bca' : '', bank_account_id: '', delivery_service: 'standard', delivery_address: '', latitude: '', longitude: '', quote_id: null, items: [] });
onMounted(() => { cart.value = readCart(props.period.id); loaded.value = true; try { const existing = sessionStorage.getItem(keyName); if (existing && !props.resetCheckoutKey) form.idempotency_key = existing; else sessionStorage.setItem(keyName, form.idempotency_key); } catch { /* Server-issued key still prevents repeated submits. */ } });
watch(cart, value => { try { sessionStorage.setItem(cartKey(props.period.id), JSON.stringify(value)); } catch { /* Checkout remains usable with the current selection. */ } }, { deep: true });
const lines = computed(() => cart.value.map((line, cartIndex) => { const result = cartLine(line, props.items); return result ? { ...result, cartIndex } : null; }).filter(Boolean));
const subtotal = computed(() => lines.value.reduce((sum, line) => sum + line.total, 0));
const selectedService = computed(() => props.period.deliveryOptions?.find(option => option.key === form.delivery_service));
const deliveryFee = computed(() => !quote.value ? 0 : selectedService.value?.feeMode === 'fixed' ? selectedService.value.fee : quote.value.fee + (selectedService.value?.fee || 0));
const deliveryTime = option => option.key === 'priority' ? `As soon as prepared · estimated ${option.minutes} minutes from ordering` : option.startsAt ? `${new Intl.DateTimeFormat('en-GB', { day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Jakarta' }).format(new Date(option.startsAt))} WIB${option.endsAt ? ' – ' + new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Jakarta' }).format(new Date(option.endsAt)) + ' WIB' : ''}` : 'Delivery time has not been set for this session';
const total = computed(() => subtotal.value + (form.method === 'delivery' ? deliveryFee.value : 0));
const invalid = computed(() => lines.value.length !== cart.value.length || lines.value.some(line => !choicesValid(line.item, line.choices) || !Number.isInteger(line.quantity) || line.quantity < 1 || line.quantity > 99 || (line.item.remaining !== null && cart.value.filter(other => other.id === line.id).reduce((sum, other) => sum + Number(other.quantity), 0) > line.item.remaining)));
watch(() => [form.latitude, form.longitude, form.method], () => { quote.value = null; form.quote_id = null; quoteError.value = ''; });
const calculate = async () => {
    quoting.value = true; quoteError.value = ''; quote.value = null; form.quote_id = null;
    const point = [form.latitude, form.longitude];
    try {
        const xsrf = document.cookie.split('; ').find(value => value.startsWith('XSRF-TOKEN='))?.slice(11);
        const response = await fetch(props.quoteUrl, { method: 'POST', headers: { 'Content-Type': 'application/json', Accept: 'application/json', 'X-XSRF-TOKEN': decodeURIComponent(xsrf || '') }, body: JSON.stringify({ latitude: point[0], longitude: point[1] }) });
        const data = await response.json();
        if (!response.ok) throw new Error(Object.values(data.errors || {}).flat()[0] || 'Delivery could not be calculated. Please retry.');
        if (point[0] !== form.latitude || point[1] !== form.longitude || form.method !== 'delivery') return;
        quote.value = data; form.quote_id = data.id;
    } catch (error) { quoteError.value = error.message; } finally { quoting.value = false; }
};
const submit = () => {
    form.items = cart.value.map(({ id, quantity, choices }) => ({ id, quantity, choices }));
    form.post(props.submitUrl, { onSuccess: () => { try { sessionStorage.removeItem(cartKey(props.period.id)); sessionStorage.removeItem(keyName); } catch { /* Receipt was already saved by the server. */ } } });
};
</script>
<template>
    <Head :title="`Checkout — ${store.name}`"/><div class="min-h-screen bg-[#f5f2ec] text-[#504941]"><main class="mx-auto max-w-6xl px-5 py-10 sm:px-8"><div class="flex items-center justify-between gap-3"><Link :href="backUrl" class="text-sm text-stone-500 hover:underline">← Back to menu</Link></div><p class="mt-8 text-xs uppercase tracking-[.2em] text-stone-500">{{ store.name }} · {{ period.name }}</p><h1 class="mt-3 text-3xl font-semibold">Your order.</h1><p class="mt-3 text-sm text-stone-500">Review your selection. No account needed.</p>
    <p v-if="loaded && !cart.length" class="mt-8 rounded-2xl bg-white p-8">Your order is empty. <Link :href="backUrl" class="underline">Choose a product</Link></p>
    <form v-else-if="loaded" class="mt-8 grid items-start gap-6 lg:grid-cols-[1fr_360px]" @submit.prevent="submit"><div class="space-y-6"><section class="rounded-3xl border border-stone-200 bg-[#fffdf9] p-6"><h2 class="text-lg font-semibold">Your selection</h2><article v-for="(line, index) in lines" :key="index" class="flex gap-4 border-b border-stone-100 py-5 last:border-0"><img v-if="line.item.imageUrl" :src="line.item.imageUrl" :alt="line.item.name" class="size-20 rounded-xl object-cover"/><div class="min-w-0 flex-1"><p class="font-medium">{{ line.item.name }}</p><p class="mt-1 text-xs leading-5 text-stone-500">{{ line.selected.map(choice => `${choice.group}: ${choice.name}`).join(' · ') }}</p><div class="mt-3 flex flex-wrap items-center justify-between gap-3"><label class="text-xs">Qty <input v-model.number="cart[line.cartIndex].quantity" type="number" min="1" max="99" class="ml-2 w-16 rounded-lg border border-stone-200 px-2 py-1.5"/></label><span class="text-sm font-medium">{{ money(line.total) }}</span><button type="button" class="text-xs text-red-700 underline" @click="cart.splice(line.cartIndex, 1)">Remove</button></div></div></article><p v-if="invalid" role="alert" class="mt-3 text-sm text-red-700">A selection or quantity is no longer available. Please update your order from the menu.</p></section>
    <section class="rounded-3xl border border-stone-200 bg-[#fffdf9] p-6"><h2 class="text-lg font-semibold">Contact details</h2><div class="mt-5 grid gap-4 sm:grid-cols-2"><label class="text-sm">Your name<input v-model="form.customer_name" required maxlength="100" autocomplete="name" class="mt-2 w-full rounded-xl border border-stone-300 bg-white px-4 py-3"/></label><label class="text-sm">WhatsApp number<input v-model="form.phone" required type="tel" maxlength="30" autocomplete="tel" aria-describedby="checkout-whatsapp-help" class="mt-2 w-full rounded-xl border border-stone-300 bg-white px-4 py-3"/><span id="checkout-whatsapp-help" class="mt-2 block text-xs leading-5 text-stone-500">An active WhatsApp number is required so the seller can contact you about your order.</span></label></div></section>
    <section class="rounded-3xl border border-stone-200 bg-[#fffdf9] p-6"><h2 class="text-lg font-semibold">How would you like to receive it?</h2><div class="mt-5 flex flex-wrap gap-3"><label v-if="period.pickup" class="flex cursor-pointer items-center gap-3 rounded-xl border border-stone-200 px-5 py-4" :class="form.method === 'pickup' ? 'bg-stone-100 border-stone-500' : ''"><input v-model="form.method" type="radio" value="pickup" class="accent-stone-700"/>Pickup</label><label v-if="period.delivery" class="flex cursor-pointer items-center gap-3 rounded-xl border border-stone-200 px-5 py-4" :class="form.method === 'delivery' ? 'bg-stone-100 border-stone-500' : ''"><input v-model="form.method" type="radio" value="delivery" class="accent-stone-700"/>Delivery</label></div><p v-if="form.method === 'pickup'" class="mt-4 text-sm leading-6 text-stone-500">Collect your order at the store. The exact pickup address and map appear once your order is ready for pickup.</p><div v-if="form.method === 'delivery'" class="mt-5 space-y-4"><label class="block text-sm">Delivery address · Required<textarea v-model="form.delivery_address" required maxlength="500" autocomplete="street-address" placeholder="Street, house number, area and delivery instructions" class="mt-2 w-full rounded-xl border border-stone-300 bg-white px-4 py-3"/></label><fieldset class="space-y-3"><legend class="mb-3 font-semibold">When would you like delivery?</legend><label v-for="option in period.deliveryOptions" :key="option.key" class="flex cursor-pointer items-start gap-3 rounded-2xl border p-4" :class="form.delivery_service === option.key ? 'border-stone-600 bg-stone-50' : 'border-stone-200'"><input v-model="form.delivery_service" type="radio" :value="option.key" class="mt-1 accent-stone-700"><span class="min-w-0 flex-1"><strong class="block text-sm">{{ option.name }}</strong><span class="mt-1 block text-sm text-stone-500">{{ deliveryTime(option) }}</span><span class="mt-2 block text-xs text-stone-500">{{ option.feeMode === 'fixed' ? money(option.fee) + ' delivery' : option.feeMode === 'extra' ? '+' + money(option.fee) + ' on top of delivery' : 'Location-based delivery fee' }}</span></span></label></fieldset><LocationPicker v-model:latitude="form.latitude" v-model:longitude="form.longitude" :tiles-url="mapTilesUrl" title="Pin your delivery location"/><button type="button" :disabled="quoting || form.latitude === '' || form.longitude === ''" class="rounded-full border border-stone-300 px-5 py-3 text-sm disabled:opacity-40" @click="calculate">{{ quoting ? 'Calculating…' : 'Calculate delivery' }}</button><p v-if="quote" role="status" class="text-sm text-green-800">{{ (quote.distance_m / 1000).toFixed(2) }} km by road · {{ money(deliveryFee) }}</p><p v-if="quote" class="text-xs leading-5 text-stone-400">Routes by <a href="https://project-osrm.org/" target="_blank" rel="noreferrer noopener" class="underline">OSRM</a> · © OpenStreetMap contributors · <a href="https://www.openstreetmap.org/fixthemap" target="_blank" rel="noreferrer noopener" class="underline">Fix the map</a></p><p v-if="routingDemo" class="text-xs text-stone-500">Delivery routing is using a shared demo service for local testing.</p><p v-if="quoteError" role="alert" class="text-sm text-red-700">{{ quoteError }}</p></div></section></div>
    <aside class="rounded-3xl border border-stone-200 bg-[#fffdf9] p-6 lg:sticky lg:top-6"><h2 class="text-lg font-semibold">Order summary</h2><div class="mt-5 space-y-3 text-sm"><p class="flex justify-between gap-4"><span>Products</span><span>{{ money(subtotal) }}</span></p><p class="flex justify-between gap-4"><span>{{ form.method === 'pickup' ? 'Pickup' : (selectedService?.name || '') + ' Delivery' }}</span><span>{{ form.method === 'delivery' && !quote ? 'Calculate first' : money(form.method === 'pickup' ? 0 : deliveryFee) }}</span></p><p class="flex justify-between gap-4 border-t border-stone-200 pt-4 text-lg font-semibold"><span>Total</span><span>{{ money(total) }}</span></p></div><fieldset class="mt-6 border-t border-stone-200 pt-5"><legend class="text-sm font-semibold">Payment method</legend><label v-if="paymentMethods.cash" class="mt-3 flex cursor-pointer items-center gap-3 rounded-xl border border-stone-200 px-4 py-3 text-sm"><input v-model="form.payment_method" type="radio" value="cash" class="accent-stone-700"/>Cash on {{ form.method }}</label><label v-if="paymentMethods.qris && !qrisClosed" class="mt-3 flex cursor-pointer items-center gap-3 rounded-xl border border-stone-200 px-4 py-3 text-sm"><input v-model="form.payment_method" type="radio" value="qris" class="accent-stone-700"/>QRIS</label><label v-if="paymentMethods.bankTransfer" class="mt-3 flex cursor-pointer items-center gap-3 rounded-xl border border-stone-200 px-4 py-3 text-sm"><input v-model="form.payment_method" type="radio" value="bank_transfer" :disabled="!gatewayAvailable && !bankAccounts.length" class="accent-stone-700"/>Bank transfer</label><p v-if="!paymentMethods.cash && !paymentMethods.bankTransfer && (!paymentMethods.qris || qrisClosed)" class="mt-3 text-sm text-amber-800">The seller has no available payment method. Please return later.</p><label v-if="form.payment_method === 'bank_transfer' && gatewayAvailable" class="mt-4 block text-sm">Payment bank<select v-model="form.payment_bank" required class="mt-2 w-full rounded-xl border border-stone-300 bg-white px-3 py-3"><option value="bca">BCA Virtual Account</option><option value="bni">BNI Virtual Account</option><option value="bri">BRI Virtual Account</option></select><span class="mt-2 block text-xs leading-5 text-stone-500">Your Virtual Account appears after checkout.</span></label><label v-if="form.payment_method === 'bank_transfer' && !gatewayAvailable" class="mt-4 block text-sm">Transfer to<select v-model="form.bank_account_id" required class="mt-2 w-full rounded-xl border border-stone-300 bg-white px-3 py-3"><option disabled value="">Choose a bank account</option><option v-for="account in bankAccounts" :key="account.id" :value="account.id">{{ account.bank_name }} · {{ account.account_holder }}</option></select></label><p v-if="paymentDeadline && form.payment_method !== 'cash'" class="mt-3 text-xs text-stone-500">Pay now · Complete before {{ new Intl.DateTimeFormat('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Jakarta' }).format(new Date(paymentDeadline)) }} WIB · 15 minutes before ordering closes.</p><p v-if="form.payment_method === 'qris' && paymentTime && !qrisClosed" class="mt-3 flex items-center justify-between rounded-xl bg-stone-100 p-3 text-sm"><span>Time left to pay</span><strong class="font-mono text-lg tabular-nums" role="timer" aria-live="off">{{ paymentTime.label }}</strong></p><p v-if="qrisClosed" role="status" class="mt-3 text-sm text-amber-800">QRIS ordering has closed.{{ paymentMethods.cash ? ' You can still choose cash until the session closes.' : '' }}</p><p v-if="form.payment_method" class="mt-3 text-xs leading-5 text-stone-500">{{ form.payment_method === 'cash' ? 'Pay when you receive your order.' : 'Scan the QR after placing your order. Payment is confirmed automatically.' }}</p></fieldset><div v-if="Object.keys(form.errors).length" role="alert" class="mt-4 space-y-2 text-sm text-red-700"><p v-for="(message, key) in form.errors" :key="key">{{ message }}</p></div><button :disabled="form.processing || !form.payment_method || (form.payment_method === 'qris' && qrisClosed) || invalid || !cart.length || period.status !== 'open' || (form.method === 'delivery' && (!form.quote_id || !form.delivery_address.trim()))" class="mt-6 w-full rounded-full bg-[#504941] px-5 py-3.5 text-sm font-semibold text-white disabled:opacity-40">{{ form.processing ? 'Placing order…' : 'Place order →' }}</button><p class="mt-3 text-xs leading-5 text-stone-500">Availability and prices are checked again when you place your order.</p></aside></form></main></div>
</template>
